package ro.leo.keypad;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import java.util.*;
/** Only Leo Visual, signed with the same key, can transfer the bounded personal dictionary. */
public final class BackupProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 public Bundle call(String method,String arg,Bundle input){String[] packages=getContext().getPackageManager().getPackagesForUid(Binder.getCallingUid());if(packages==null||!Arrays.asList(packages).contains("ro.leo.visual"))throw new SecurityException("Leo Visual only");Bundle out=new Bundle();if(method.equals("snapshot")){out.putString("words",getContext().getSharedPreferences("personal-words",0).getString("words",""));out.putInt("mode",getContext().getSharedPreferences("keypad",0).getInt("mode",0));return out;}if(!method.equals("validate")&&!method.equals("restore"))throw new IllegalArgumentException();String words=input.getString("words","");int mode=input.getInt("mode",0);if(words.length()>16384||mode<0||mode>4)throw new IllegalArgumentException("Invalid dictionary");PersonalWords clean=new PersonalWords();clean.load(words);if(!clean.save().equals(words))throw new IllegalArgumentException("Dictionary must be canonical");if(method.equals("restore")){if(!getContext().getSharedPreferences("personal-words",0).edit().putString("words",words).commit())throw new IllegalStateException();if(!getContext().getSharedPreferences("keypad",0).edit().putInt("mode",mode).commit())throw new IllegalStateException();}out.putBoolean("ok",true);return out;}
 public Cursor query(Uri u,String[] p,String s,String[] a,String o){throw new UnsupportedOperationException();}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
